const photos=[{key:'sofas',file:'sofa-1.png',name:'Sofá de dois lugares',description:'Lavagem e revitalização de sofá claro'},{key:'sofas',file:'sofa-2.png',name:'Sofá de três lugares',description:'Cuidado com marcas do uso diário'},{key:'sofas',file:'sofa-3.png',name:'Sofá retrátil',description:'Renovação do seu espaço de descanso'},{key:'poltronas',file:'poltrona-1.png',name:'Poltrona capitonê',description:'Atenção aos detalhes do estofado'},{key:'poltronas',file:'poltrona-2.png',name:'Poltrona com braços de madeira',description:'Limpeza do assento e do encosto'},{key:'colchoes',file:'colchao-1.png',name:'Colchão de casal',description:'Higienização para renovar o descanso'},{key:'colchoes',file:'colchao-2.png',name:'Colchão estampado',description:'Cuidado especializado com o colchão'},{key:'cadeiras',file:'cadeiras-1.png',name:'Cadeira de jantar',description:'Limpeza do assento e do encosto'}];
let filteredPhotos=photos,activePhoto=0;
const galleryGrid=document.getElementById('gallery-grid'),dialog=document.getElementById('photo-dialog');
function renderGallery(filter,updateURL=false){if(!['todos',...services.map(s=>s.key)].includes(filter))filter='todos';filteredPhotos=filter==='todos'?photos:photos.filter(p=>p.key===filter);document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));document.getElementById('gallery-count').textContent=filteredPhotos.length+(filteredPhotos.length===1?' transformação':' transformações');galleryGrid.innerHTML=filteredPhotos.map((p,i)=>`<article class="gallery-card"><button class="gallery-photo" data-photo="${i}" aria-label="Ampliar antes e depois: ${p.name}"><img src="/assets/${p.file}" alt="Antes e depois: ${p.name}" loading="${i<3?'eager':'lazy'}" width="560" height="550"><span class="zoom-label">Ampliar imagem <span aria-hidden="true">＋</span></span></button><div class="gallery-card-content"><p class="eyebrow">${services.find(s=>s.key===p.key).name}</p><h2>${p.name}</h2><p>${p.description}</p><a class="service-link" data-whatsapp="${p.key}">Quero esse resultado <span class="wa-icon"></span></a></div></article>`).join('');const cta=document.getElementById('gallery-cta');cta.dataset.whatsapp=filter==='todos'?'geral':filter;bindWhatsApp();if(updateURL){const url=new URL(location.href);if(filter==='todos')url.searchParams.delete('servico');else url.searchParams.set('servico',filter);history.pushState({},'',url)}galleryGrid.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>{activePhoto=Number(b.dataset.photo);updateDialog();dialog.showModal();document.body.classList.add('dialog-open')}))}
function updateDialog(){const p=filteredPhotos[activePhoto];document.getElementById('dialog-image').src='/assets/'+p.file;document.getElementById('dialog-image').alt='Antes e depois: '+p.name;document.getElementById('dialog-title').textContent=p.name;document.getElementById('dialog-position').textContent=`${activePhoto+1} de ${filteredPhotos.length} · Fotos originais do serviço`;document.getElementById('dialog-cta').dataset.whatsapp=p.key;document.getElementById('previous-photo').disabled=filteredPhotos.length<2;document.getElementById('next-photo').disabled=filteredPhotos.length<2;bindWhatsApp(dialog)}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>renderGallery(b.dataset.filter,true)));
document.getElementById('close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.classList.remove('dialog-open'));dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function nextPhoto(direction){activePhoto=(activePhoto+direction+filteredPhotos.length)%filteredPhotos.length;updateDialog()}
document.getElementById('previous-photo').addEventListener('click',()=>nextPhoto(-1));document.getElementById('next-photo').addEventListener('click',()=>nextPhoto(1));dialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();nextPhoto(-1)}if(e.key==='ArrowRight'){e.preventDefault();nextPhoto(1)}});window.addEventListener('popstate',()=>renderGallery(new URLSearchParams(location.search).get('servico')||'todos'));renderGallery(new URLSearchParams(location.search).get('servico')||'todos');
